<?php
require_once __DIR__.'/bootstrap.php';$user=current_user($pdo);$term=trim((string)($_GET['q']??''));$people=[];
if($term!==''){$q=$pdo->prepare('SELECT username,display_name,bio FROM users WHERE username LIKE ? OR display_name LIKE ? ORDER BY username LIMIT 25');$search='%'.str_replace(['%','_'],['\\%','\\_'],$term).'%';$q->execute([$search,$search]);$people=$q->fetchAll();}
page_top('Search',$user);?><div class="heading"><strong>Search</strong></div><form class="search-form" method="get"><input name="q" type="search" maxlength="80" placeholder="Search people" value="<?=e($term)?>" autofocus><button class="pill">Search</button></form>
<?php if($term!==''):?><div class="section-label">People</div><?php foreach($people as $person):?><a class="person" href="profile.php?u=<?=rawurlencode($person['username'])?>"><div class="avatar"><?=e(mb_strtoupper(mb_substr($person['display_name'],0,1)))?></div><div><strong><?=e($person['username'])?></strong><p class="muted"><?=e($person['display_name'])?></p><p><?=e($person['bio'])?></p></div></a><?php endforeach;if(!$people)echo '<div class="empty">No accounts found.</div>';else echo '<div class="empty end">End of results</div>';endif;page_bottom(); ?>
